using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings() =>
        JsonSerializer.Serialize(new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { EnableCaching = true, EnableLogging = true }
        }, JsonOptions);

    [McpServerResource(UriTemplate = "config://app/status", Name = "Server Status",
        MimeType = "application/json"),
     Description("Returns the current server status including uptime.")]
    public static string GetServerStatus() =>
        JsonSerializer.Serialize(new
        {
            Status = "Healthy",
            StartedAt = Program.StartedAt,
            Uptime = DateTime.UtcNow - Program.StartedAt
        }, JsonOptions);
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class EchoTools
{
    [McpServerTool, Description("Echoes back the provided message with a timestamp.")]
    public static string Echo(
        [Description("The message to echo back")] string message) =>
        $"[{DateTime.UtcNow:O}] {message}";

    [McpServerTool, Description("Converts text to uppercase.")]
    public static string ToUpper(
        [Description("The text to convert")] string text) =>
        text.ToUpperInvariant();
}

